# All cleaning, integration, trajectories, tests and figures use R.
a<-grep('^--file=',commandArgs(),value=TRUE);root<-dirname(normalizePath(sub('^--file=','',a[1])))
run<-function(p){cat('\nRunning ',p,'\n');status<-system2(file.path(R.home('bin'),'Rscript'),shQuote(file.path(root,p)));stopifnot(status==0)}
for(p in c('scripts/00_audit_inputs.R','scripts/01_integrate.R','scripts/02_trajectory_projection.R','scripts/02b_prepare_local_support_inputs.R','panel_g/scripts/00_constrain_Ridge_to_P41_reference_local_support.R','scripts/02c_install_constrained_mapping.R','scripts/03_shared_GAM.R','scripts/04_diagnostics.R','scripts/06_complete_exports.R','panel_c/scripts/00_refit_shared_Gaussian_GAM_curves.R','00_redraw_all_panels_and_preview.R','panel_h/scripts/02_export_all_pathway_member_statistics.R','01_create_vector_overview.R','02_validate_shared_GAM_results.R','matrix/scripts/01_build_annotated_cell_feature_master.R','scripts/07_interactive_report.R','scripts/08_final_audit.R'))run(p)
